    fn credentials(&self) -> Result<AwsCredentials, CredentialsError>;
}

impl ProvideAwsCredentials for AwsCredentials {
    fn credentials(&self) -> Result<AwsCredentials, CredentialsError> {
        Ok(self.clone())
    }
