    /// Registers a new `PredicateObligation` with this fulfillment context.
    ///
    /// This method adds the obligation to the list of pending obligations
    /// and returns `true` if the obligation was added (i.e., it was not already
    /// present in the `duplicate_set`).
    pub fn register_predicate_obligation(&mut self, infcx: &InferCtxt<'_, 'tcx>, obligation: PredicateObligation<'tcx>) -> bool {
        let predicate = obligation.predicate;

        if self.duplicate_set.set.contains(&predicate) {
            return false;
        }

        self.duplicate_set.set.insert(predicate);
        self.predicates.push(obligation);
        true
    }

    /// Registers a new region obligation with this fulfillment context.
    ///
    /// This method adds the obligation to the list of pending region obligations
    /// for the given node ID.
    pub fn register_region_obligation(&mut self, node_id: ast::NodeId, obligation: RegionObligation<'tcx>) {
        self.region_obligations.entry(node_id).or_insert_with(Vec::new).push(obligation);
    }

