/// Returns a vector of keys that are in `a` but not in `b`
fn diff_left<'a, T: std::cmp::Eq + std::hash::Hash + 'a>(a: T, b: &std::collections::HashSet<String>) -> Vec<String>
where
    T: IntoIterator<Item = &'a String>,
{
