fn print_field(field: &Vec<Vec<Field>>) {
    for row in field.iter() {
        for c in row.iter() {
            print!("{}", match c.active {false => " ", true => "#"});
        }
        print!("\n");
    }
    print!("\n");
}

fn generate_first_round() -> Vec<Vec<Field>> {
