        // Ensure the remaining length matches the expected length
        let expected_length = packet.encoded_variable_headers_length() + packet.payload.encoded_length();
        if packet.fixed_header.remaining_length != expected_length {
            return Err(PacketError::InvalidRemainingLength.into());
        }

        Ok(packet)
    }

