        self.fixed_header.encode(writer)?;
        self.packet_identifier.encode(writer)?;
        self.payload.encode(writer)?;
        Ok(())
    }

    fn encoded_length(&self) -> usize {
        self.fixed_header.encoded_length() +
        self.packet_identifier.encoded_length() +
        self.payload

