            impl<'a> Add<RowVec<$t>> for $t {
                type Output = RowVec<$t>;

                fn add(self, mut rhs: RowVec<$t>) -> RowVec<$t> {
                    rhs.add_assign(self);
                    rhs
                }
            }
         )+
    };
}

