impl<T> AsyncRead for Rewind<T>
where
    T: AsyncRead,
{
    #[inline]
    fn poll_read(&mut self, cx: &mut Context<'_>, buf: &mut [u8]) -> Poll<io::Result<usize>> {
        if let Some(pre_bs) = self.pre.take() {
            if pre_bs.len() > 0 {
                let mut pre_reader = pre_bs.into_buf().reader();
                match pre_reader.poll_read(cx, buf)? {
                    Async::Ready(read_cnt) => {
                        let mut new_pre = pre_reader.into_inner().into_inner();
                        new_pre.advance(read_cnt);

                        if new_pre.len() > 0 {
                            self.pre = Some(new_pre);
                        }

                        return Ok(Async::Ready(read_cnt));
                    }
                    Async::NotReady => {
                        // Put back the buffer if not all bytes were read
                        self.pre = Some(pre_reader.into_inner().into_inner());
                        return Ok(Async::NotReady);
                    }
                }
            }
        }

        self.inner.poll_read(cx, buf)
    }
}

