            expect!(DirectedCycle::new(&graph)).to(be_err());
        }

        it "should have a cycle" {
            graph.add_edge(1, 2);
            graph.add_edge(2, 3);
            graph.add_edge(3, 1);

            let cycle = DirectedCycle::new(&graph).unwrap();

            expect!(cycle.has_cycle()).to(be_true());
        }

        it "should not have a cycle" {
            graph.add_edge(1, 2);
            graph.add_edge(2, 3);
            graph.add_edge(1, 4);

            let cycle = DirectedCycle::new(&graph).unwrap();

            expect!(cycle.has_cycle()).to(be_false());
        }
    }
